package cli

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Check only directories that this invocation writes. Generated files left by
// renamed queries or models can break a build even when every expected file
// matches. Report them before writing; never delete files on the user's behalf.
func checkStaleOutputs(files []output) error {
	expected := map[string]map[string]bool{}
	for _, f := range files {
		dir, err := canonicalPath(filepath.Dir(f.path))
		if err != nil {
			return err
		}
		if expected[dir] == nil {
			expected[dir] = map[string]bool{}
		}
		expected[dir][filepath.Base(f.path)] = true
	}
	dirs := make([]string, 0, len(expected))
	for dir := range expected {
		dirs = append(dirs, dir)
	}
	sort.Strings(dirs)
	var stale []string
	for _, dir := range dirs {
		entries, err := os.ReadDir(dir)
		if errors.Is(err, os.ErrNotExist) {
			continue
		}
		if err != nil {
			return err
		}
		for _, entry := range entries {
			// Do not walk nested packages or follow unrelated symbolic links.
			if expected[dir][entry.Name()] || !entry.Type().IsRegular() {
				continue
			}
			path := filepath.Join(dir, entry.Name())
			generated, err := hasGeneratedHeader(path)
			if err != nil {
				return err
			}
			if generated {
				stale = append(stale, path)
			}
		}
	}
	if len(stale) != 0 {
		return fmt.Errorf("stale generated files; remove them before generating or use a separate output directory for each configuration:\n%s", strings.Join(stale, "\n"))
	}
	return nil
}

func hasGeneratedHeader(path string) (bool, error) {
	file, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer file.Close()
	var header [64]byte
	n, err := io.ReadFull(file, header[:])
	if err != nil && !errors.Is(err, io.EOF) && !errors.Is(err, io.ErrUnexpectedEOF) {
		return false, fmt.Errorf("read %s: %w", path, err)
	}
	line, _, found := bytes.Cut(header[:n], []byte("\n"))
	line = bytes.TrimSuffix(line, []byte("\r"))
	return found && (bytes.Equal(line, []byte("// Code generated by sqlc-ydb. DO NOT EDIT.")) ||
		bytes.Equal(line, []byte("# Code generated by sqlc-ydb. DO NOT EDIT."))), nil
}
